with open('/Users/a/illumini-senior-engineer-takehome/tests/v2/golden-dataset/user_search_inputs/profile_a/job_title_searches.json') as f:
    title_profile = json.load(f)
with open('/Users/a/illumini-senior-engineer-takehome/tests/v2/golden-dataset/user_search_inputs/profile_a/location_searches.json') as f:
    location_profile = json.load(f)

STRIP_SUFFIXES = re.compile(r'\b(ltd|plc|group|holdings|international|uk|limited|inc|llc|corp|co)\b\.?', re.I)

def normalize_company(name):
    n = name.lower()
    n = re.sub(r'[^\w\s]', ' ', n)
    n = re.sub(r'\bthe\b', '', n)
    n = STRIP_SUFFIXES.sub('', n)
    return re.sub(r'\s+', ' ', n).strip()

def company_matches(job, profile_companies):
    """Check if any profile company appears in job page signals."""
    page = job.get('page', {})
    # gather all text signals
    signals = []
    scraped = job.get('scraped', {})
    if scraped.get('company'): signals.append(scraped['company'])
    if page.get('title_tag'): signals.append(page['title_tag'])
    if page.get('h1'): signals.append(page['h1'])
    if page.get('text'): signals.append(page['text'][:2000])
    if page.get('meta', {}) and isinstance(page.get('meta'), dict):
        for v in page['meta'].values():
            if isinstance(v, str): signals.append(v)
    if job.get('source_url'): signals.append(job['source_url'])

    combined = ' '.join(signals).lower()

    for co in profile_companies:
        norm = normalize_company(co['name'])
        # also try each word
        if norm and norm in combined:
            return co['name']
        # try individual words approach for multi-word companies
        words = norm.split()
        if len(words) >= 2:
            # check if all words present
            if all(w in combined for w in words if len(w) > 2):
                return co['name']
    return None

def title_matches(job, profile_titles):
    """Check if every word of any profile title appears in job title."""
    job_title = ''
    page = job.get('page', {})
    scraped = job.get('scraped', {})

    candidates = []
    if scraped.get('title'): candidates.append(scraped['title'])
    if page.get('h1'): candidates.append(str(page['h1']))
    if page.get('title_tag'): candidates.append(page['title_tag'])

    matched = []
    for pt in profile_titles:
        pt_words = re.findall(r'[a-z]+', pt.lower())
        for candidate in candidates:
            jt_words = re.findall(r'[a-z]+', candidate.lower())
            # trailing plural s: strip s from both
            def strip_plural(w): return w[:-1] if w.endswith('s') else w
            jt_stripped = [strip_plural(w) for w in jt_words]
            if all(strip_plural(w) in jt_stripped for w in pt_words):
                matched.append(pt)
                break
    return matched

def all_location_towns(profile_locations):
    """Return flat set of all towns covered by any profile location (UK only)."""
    towns = set()
    for loc in profile_locations:
        if loc.get('country') != 'United Kingdom':
            continue
        towns.add(loc['name'].lower())
        for inc in loc.get('includes', []):
            towns.add(inc.lower())
    return towns

def is_remote_covered(job, profile_locations):
    page = job.get('page', {})
    text = ' '.join(filter(None, [
        page.get('text',''), page.get('title_tag',''), page.get('h1',''),
        job.get('scraped',{}).get('location','')
    ])).lower()
    for loc in profile_locations:
        if loc.get('type') == 'remote' and loc.get('country') == 'United Kingdom':
            for kw in loc.get('includes', []):
                if kw.lower() in text:
                    return True
    return False

def location_matches(job, profile_locations):
    """Check if job location matches any profile location."""
    covered_towns = all_location_towns(profile_locations)

    scraped_loc = job.get('scraped', {}).get('location', '') or ''
    page = job.get('page', {})

    # gather location signals
    loc_signals = [scraped_loc]
    if page.get('text'): loc_signals.append(page['text'][:3000])
    if page.get('title_tag'): loc_signals.append(page['title_tag'])
    if page.get('h1'): loc_signals.append(str(page.get('h1','')))

    combined = ' '.join(loc_signals).lower()

    matched = []
    for loc in profile_locations:
        if loc.get('country') != 'United Kingdom':
            continue
        if loc.get('type') == 'remote':
            for kw in loc.get('includes', []):
                if kw.lower() in combined:
                    matched.append(loc['name'])
                    break
        else:
            check_names = [loc['name']] + loc.get('includes', [])
            for name in check_names:
                if name.lower() in combined:
                    matched.append(loc['name'])
                    break
    return matched

